    'DECISIÓN: nada se envía hasta que lo apruebes (etiqueta «aprobado-para-contactar»; para descartar «descartado-prospecto»).');
  return lines.join('\n').replace(/\n{3,}/g, '\n\n').slice(0, 7000);
