function toList(v) {
  if (Array.isArray(v)) return v.map((x) => (typeof x === 'string' ? x : x && (x.text || x.finding || x.url) ? String(x.text || x.finding || x.url) : '')).map((x) => x.trim()).filter(Boolean);
