function businessDaysFrom(nowMs, n) {
  const d = new Date(nowMs);
  d.setUTCHours(15, 0, 0, 0);
  let left = Math.max(0, n);
  while (left > 0) { d.setUTCDate(d.getUTCDate() + 1); if (d.getUTCDay() !== 0 && d.getUTCDay() !== 6) left--; }
  return d.toISOString();
}

