  const hermesLint = c.suggested_email ? lintOutreach(subject, c.suggested_email, company) : ['sin_borrador_previo'];
  const useGiven = c.suggested_email && !hermesLint.length && !/^Asunto:/i.test(c.suggested_email.trim() ? '' : '');
