      if (m) { lastKey = m[1].trim(); rec[lastKey] = (rec[lastKey] ? rec[lastKey] + '\n' : '') + m[2].trim(); }
      else if (lastKey && ln.trim()) rec[lastKey] += '\n' + ln.trim();
